contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // parameter present so the checker treats this as a ranged input; unused but required
    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // record balances before
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // attempt refund; top-level state-changing call
        bool refundedReverted;
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            refundedReverted = true;
        } else {
            refundedReverted = false;
        }

        // record after balances
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // If refund reverted: no observable change. If it succeeded: contract's balance decreased by exactly
        // the amount this contract gained (no Ether created).
        assert(
            (refundedReverted && afterC == beforeC && afterThis == beforeThis)
            || (!refundedReverted
                && beforeC >= afterC
                && afterThis >= beforeThis
                && (beforeC - afterC) == (afterThis - beforeThis))
        );
    }

    receive() external payable { }
}

